use vstd::prelude::*;

verus! {

/// Spec-level predicate: whether a character is an ASCII digit.
pub spec fn spec_is_ascii_digit(c: char) -> bool {
    '0' <= c && c <= '9'
}

pub fn is_ascii_digit(c: char) -> (b: bool)
    ensures
        b == spec_is_ascii_digit(c),
{
    matches!(c, '0'..='9')
}

/// Spec-level predicate for a string: all characters are ASCII digits.
///
/// Note: `String::chars()` iterates over Unicode scalar values (Rust `char`s),
/// which is what we quantify over here via `str@.chars()`.
pub spec fn spec_all_digits(str: Seq<char>) -> bool {
    forall|i: int| 0 <= i < str.len() ==> spec_is_ascii_digit(str[i])
}

pub fn all_digits(s: String) -> (ok: bool)
    ensures
        ok == spec_all_digits(s@.chars()),
{
    // Vacuously true for the empty string; iterates over Unicode scalar values (chars).
    for ch in s.chars() {
        if !is_ascii_digit(ch) {
            return false;
        }
    }
    true
}

} // verus!

